typedef struct
{
  float version;
  int type;
  char shortname[8];
  char desc[68];
  long int timestamp;
  int valid;
} saveInfo;

typedef struct
{
  char data[96];
} sceMcTblGetDir;

extern "C" char *strcpy(char *, const char *);
extern "C" char *strcat(char *, const char *);
extern "C" int sceMcGetDir(int, int, const char *, int, int, sceMcTblGetDir *);
extern "C" int sceMcSync(int, int *, int *);

#define CAREER_DATA_VERSION 68168
#define PRODUCT_CODE "BASLUS-20334"
#define GSOk 0
#define GSErrorOther -2

class GenericGameSaver
{
public:
  static int getInfo(int port, int slot, int *type, int *free, int *formatted);
  int isFileValid(int port, int slot, saveInfo s);
};

int GenericGameSaver::isFileValid( int port, int slot, saveInfo s )
{
  char iconname[100];
  sceMcTblGetDir tble[1] __attribute__((aligned (64)));;
  int free, formatted, type, cmd, result;
  char shortname[20];
  strcpy(shortname, s.shortname);

  shortname[7] = '\0';

  if (s.version != CAREER_DATA_VERSION)
    return GSErrorOther;
  if (getInfo(port, slot, &type, &free, &formatted) < 0)
    return GSErrorOther;
  strcpy(iconname, "/");
  strcat(iconname, PRODUCT_CODE);
  strcat(iconname, shortname);
  strcat(iconname, "/");
  strcat(iconname, PRODUCT_CODE);
  strcat(iconname, shortname);
  strcat(iconname, ".icn");


  if (sceMcGetDir(port, slot, iconname , 0, 1, tble) != 0)
    if (sceMcGetDir(port, slot, iconname , 0, 1, tble) != 0)
      return GSErrorOther;

  if (sceMcSync(0, &cmd, &result) != 1)
    return GSErrorOther;
  if (result == -4)
    return GSErrorOther;
  else if (result < 0)
    return GSErrorOther;


  return GSOk;
}
